def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_last, opp_last = history[-1]

    start = n - (10 if n > 10 else n)
    opp_d_rec = 0
    my_d_rec = 0
    for i in range(start, n):
        if history[i][0] == 'D':
            my_d_rec += 1
        if history[i][1] == 'D':
            opp_d_rec += 1

    unprov = 0
    provoked = 0
    forgiven = 0
    for i in range(n):
        opp = history[i][1]
        if opp == 'D':
            if i == 0 or history[i - 1][0] == 'C':
                unprov += 1
            else:
                provoked += 1
        elif i > 0 and history[i - 1][0] == 'D':
            forgiven += 1

    if n == 98:
        if opp_d_rec >= 3 or unprov >= 1:
            return 'D'
        if provoked > forgiven:
            return 'C'
        return 'D'

    if opp_last == 'D':
        if n >= 2 and history[-2][1] == 'D':
            if unprov <= 2 and provoked >= unprov + 2 and my_d_rec >= opp_d_rec - 1:
                return 'C'
            return 'D'

        if unprov >= max(3, n // 5) or opp_d_rec >= 5:
            return 'D'

        if n >= 97 and unprov >= 1:
            return 'D'

        if my_last == 'D':
            if opp_d_rec >= 4 or unprov >= 3:
                return 'D'
            return 'C'

        return 'C'

    if my_last == 'D':
        if provoked > forgiven:
            return 'C'
        if forgiven >= 1 or opp_d_rec == 0 or n >= 95:
            return 'D'
        return 'C'

    if opp_d_rec == 0 and n > 5:
        if forgiven > provoked:
            return 'D'
        if unprov == 0 and my_d_rec == 0 and rng.random() < 0.08:
            return 'D'

    if opp_d_rec <= 1 and unprov <= 1 and forgiven >= provoked and rng.random() < 0.04:
        return 'D'

    return 'C'
